// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] calldata addrs) public {
        vm.assume(addrs.length > 0 && addrs.length <= 10);
        for (uint256 i = 0; i < addrs.length; i++) {
            vm.assume(addrs[i] != address(0));
        }

        // The test fails if addNodeDelegatorContractToQueue does not revert when c.paused() returns true
        // Since the reference correctly reverts with "Pausable: paused" and the buggy version does not,
        // we check that a revert occurs.

        vm.expectRevert("Pausable: paused");
        c.addNodeDelegatorContractToQueue(addrs);

        // The assertion below must be true: we expect a revert, so this line is unreachable.
        // But to have a general rule, we state that the contract is paused (the default after initialization).
        assertTrue(c.paused());
    }
}

