pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address[] dummy;

    function setUp() public { 
        c = new C();
        dummy = new address[](1);
        dummy[0] = address(1);
    }

    function testFuzz_property(address lrtConfigAddr, uint256 numCalls) public {
        vm.assume(lrtConfigAddr != address(0));
        vm.assume(numCalls < 10);

        // Initialize the contract
        c.initialize(address(this));

        // Track the number of calls to addNodeDelegatorContractToQueue
        uint256 totalAdded = 0;

        for (uint256 i = 0; i < numCalls; i++) {
            // Update LRT config with our fuzzed address
            c.updateLRTConfig(lrtConfigAddr);

            // Try to add node delegators
            address[] memory contracts = new address[](1);
            contracts[0] = address(uint160(i + 2)); // avoid zero address

            // Record how many we attempt to add (before potential revert)
            uint256 oldLength = c.nodeDelegatorQueueLength();

            // Call addNodeDelegatorContractToQueue
            c.addNodeDelegatorContractToQueue(contracts);

            // If successful, the queue should have grown by 1
            uint256 newLength = c.nodeDelegatorQueueLength();
            if (newLength > oldLength) {
                totalAdded++;
            }
        }

        // General rule: the length of nodeDelegatorQueue is at least totalAdded
        assertTrue(c.nodeDelegatorQueueLength() >= totalAdded);
    }
}

