pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address lrtConfigAddr, address[] calldata nodeDelegatorContracts) public {
        vm.assume(lrtConfigAddr != address(0));
        vm.assume(nodeDelegatorContracts.length <= 10);
        for (uint256 i = 0; i < nodeDelegatorContracts.length; i++) {
            vm.assume(nodeDelegatorContracts[i] != address(0));
        }

        // Initialize with the fuzzed lrtConfigAddr
        c.initialize(lrtConfigAddr);

        // Call addNodeDelegatorContractToQueue with the fuzzed array
        c.addNodeDelegatorContractToQueue(nodeDelegatorContracts);

        // The rule: lrtConfig address stored in the contract equals the one we set
        // We cannot read lrtConfig directly because it's not public, but we can call updateLRTConfig
        // and then verify the effect via the contract's public getters or events.
        // Since lrtConfig is used in onlySupportedAsset modifier, we can check if an asset is supported
        // by calling getAssetDistributionData which uses onlySupportedAsset.
        // If the lrtConfig is correct, it won't revert; if wrong, it will revert.
        // But we need a deterministic assertion. Instead, we note that after initialize,
        // the lrtConfig is set correctly. The mutation does not affect this test because
        // updateLRTConfig is not called. The difference between P and M is that in updateLRTConfig,
        // the emit happens before assignment in M. But here we don't call updateLRTConfig,
        // so both P and M have the same lrtConfig. 
        // To trigger the bug, we need to call updateLRTConfig after initialize.
        // But the problem statement says the test must end with a call to addNodeDelegatorContractToQueue.
        // So we set up lrtConfig correctly, then after addNodeDelegatorContractToQueue,
        // we check that the lrtConfig is still the one we set (since updateLRTConfig wasn't called).
        // However, the mutation does not affect this scenario.
        // To actually catch the bug, we need to call updateLRTConfig before addNodeDelegatorContractToQueue.
        // Let's modify the test to include that:
    }

    function testFuzz_property2(address lrtConfigAddr1, address lrtConfigAddr2, address[] calldata nodeDelegatorContracts) public {
        vm.assume(lrtConfigAddr1 != address(0));
        vm.assume(lrtConfigAddr2 != address(0));
        vm.assume(lrtConfigAddr1 != lrtConfigAddr2);
        vm.assume(nodeDelegatorContracts.length <= 10);
        for (uint256 i = 0; i < nodeDelegatorContracts.length; i++) {
            vm.assume(nodeDelegatorContracts[i] != address(0));
        }

        c.initialize(lrtConfigAddr1);
        // Now call updateLRTConfig with a new address
        c.updateLRTConfig(lrtConfigAddr2);
        // Now call addNodeDelegatorContractToQueue
        c.addNodeDelegatorContractToQueue(nodeDelegatorContracts);

        // After the mutation, the emit in updateLRTConfig happens before the assignment,
        // but that doesn't affect the stored lrtConfig value. The stored value is still lrtConfigAddr2.
        // The mutation only changes the order of emit and assignment, not the final stored value.
        // So this test also cannot detect the mutation.
        // The actual difference is: in M, when updateLRTConfig is called, the emit uses the OLD lrtConfig,
        // not the new one. But the stored value is still updated correctly.
        // To detect this, we need to check the event emitted during updateLRTConfig.
        // But the test cannot observe events directly. However, we can check the behavior
        // of functions that depend on lrtConfig. Since lrtConfig is updated correctly in both,
        // the behavior is the same.
        // Therefore, there is no functional difference between P and M for this mutation.
        // The test cannot distinguish them.
    }
}

