// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 maxCount, address[] memory nodes) public {
        // Bound maxCount to avoid overflow, but keep it realistic
        maxCount = bound(maxCount, 0, 100);

        // Update maxNodeDelegatorCount
        c.updateMaxNodeDelegatorCount(maxCount);

        // Try adding nodes until we either succeed or hit the limit
        bool reverted = false;
        vm.startPrank(address(this));
        for (uint256 i = 0; i < nodes.length; i++) {
            address[] memory singleNode = new address[](1);
            singleNode[0] = nodes[i];
            (bool success, ) = address(c).call(abi.encodeWithSelector(c.addNodeDelegatorContractToQueue.selector, singleNode));
            if (!success) {
                reverted = true;
                break;
            }
        }
        vm.stopPrank();

        // After the loop, either:
        // - we reverted (meaning we hit the limit), and the queue length must <= maxNodeDelegatorCount
        // - we didn't revert, meaning we added all nodes successfully, and queue length <= maxNodeDelegatorCount
        uint256 queueLength = c.getNodeDelegatorQueue().length;
        assertTrue(queueLength <= c.maxNodeDelegatorCount());
    }
}

