pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address asset, uint256 amount) public {
        // Ensure asset is not zero and is supported
        vm.assume(asset != address(0));
        // We need a node delegator contract
        address nodeDelegator = address(0xdead);
        // Deploy a minimal contract that can receive ETH and tokens? For simplicity, we assume the node delegator exists
        // But we cannot deploy arbitrary contracts in this fuzz, so we use a fixed address and deal it some token balance.
        // However, the test must be general; use a bound to ensure the asset is not waste?
        // Actually, we can use vm.etch to make it a contract?
        // Better: we just test the property that after addNodeDelegatorContractToQueue (with some address), the total deposits >= balanceOf(c) + sum of balances of node delegators.
        // Since we cannot getAssetDistributionData directly, we check that getTotalAssetDeposits(asset) >= IERC20(asset).balanceOf(address(c)).
        // This is true for reference (all terms non-negative) but false for bug if staked > lyingInNDCs.
        // So we ensure that for the reference, the total is at least the deposit pool balance.

        // First, prepare an array with a node delegator address
        address[] memory ndcs = new address[](1);
        ndcs[0] = nodeDelegator;

        // mint some tokens to the node delegator to make the bug manifest
        vm.prank(nodeDelegator);
        // If asset is an ERC20, we need to mint? Use vm.store to manipulate balance? Not possible generically.
        // Use a simpler approach: test that the sum property holds after adding, using only available getters.
        // The bug subtracts staked, so totalDeposits may be less than pool balance if staked > lyingInNDCs.
        // We can force that scenario by having no tokens, just checking the formula?
        // For the reference, getTotalAssetDeposits = pool + lying + staked >= pool (since lying+staked>=0).
        // For bug, getTotalAssetDeposits = pool + lying - staked, which could be < pool if staked > lying.
        // So we need a node delegator with staked > lying. We cannot set staked arbitrarily without contract storage.
