import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory addrs) public {
        vm.assume(addrs.length > 0 && addrs.length <= 10);
        for (uint i = 0; i < addrs.length; i++) {
            vm.assume(addrs[i] != address(0));
        }
        address[] memory before = c.getNodeDelegatorQueue();
        uint beforeLen = before.length;

        // Call addNodeDelegatorContractToQueue
        c.addNodeDelegatorContractToQueue(addrs);

        address[] memory after = c.getNodeDelegatorQueue();
        uint afterLen = after.length;

        assertTrue(afterLen == beforeLen + addrs.length, "Length should increase by number of added contracts");
    }
}

