pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address asset) public {
        vm.assume(asset != address(0));
        // Ensure the asset is supported
        address[] memory empty = new address[](0);
        c.addNodeDelegatorContractToQueue(empty);
        // Compute expected: only pool balance (no NDCS)
        uint256 expectedBalance = IERC20(asset).balanceOf(address(c));
        // Compare to getTotalAssetDeposits
        assertTrue(c.getTotalAssetDeposits(asset) == expectedBalance);
    }
}

