pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address asset, address nodeDelegator) public {
        vm.assume(nodeDelegator != address(0) && nodeDelegator.code.length > 0);
        address[] memory nds = new address[](1);
        nds[0] = nodeDelegator;
        c.addNodeDelegatorContractToQueue(nds);

        (uint256 poolBal, uint256 ndcBal, uint256 staked) = c.getAssetDistributionData(asset);
        uint256 totalDeposits = c.getTotalAssetDeposits(asset);

        assertTrue(poolBal + ndcBal + staked == totalDeposits);
    }
}

