pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address asset) public {
        vm.assume(asset != address(0));
        // Ensure the contract has some balance of the asset
        deal(asset, address(c), 1 ether);
        // Add a dummy node delegator (address this) to change the queue
        address[] memory ndcs = new address[](1);
        ndcs[0] = address(this);
        // Call addNodeDelegatorContractToQueue - this is the boundary call
        c.addNodeDelegatorContractToQueue(ndcs);
        // Get total asset deposits
        uint256 totalDeposits = c.getTotalAssetDeposits(asset);
        // Get asset lying in deposit pool
        (uint256 assetLyingInDepositPool, , ) = c.getAssetDistributionData(asset);
        // The rule: assetLyingInDepositPool should be <= totalDeposits
        assertTrue(assetLyingInDepositPool <= totalDeposits);
    }
}

